 ON cohort.subject_id = person.person_id
 ) raw_data;
INSERT INTO @temp_database_schema.rwdfeatxcov_ref (
 covariate_id,
 covariate_name,
 analysis_id,
 concept_id
 )
SELECT covariate_id,
 CAST('age in years' AS STRING) AS covariate_name,
 2 AS analysis_id,
 0 AS concept_id
FROM (
 SELECT DISTINCT covariate_id
 FROM @temp_database_schema.rwdfeatxcov_9
 ) t1;
INSERT INTO @temp_database_schema.rwdfeatxanalysis_ref (
 analysis_id,
 analysis_name,
 domain_id,
 start_day,
 end_day,
 is_binary,
 missing_means_zero
 )
SELECT 2 AS analysis_id,
 CAST('DemographicsAge' AS STRING) AS analysis_name,
 CAST('Demographics' AS STRING) AS domain_id,
 CAST(NULL AS INT) AS start_day,
 CAST(NULL AS INT) AS end_day,
 CAST('N' AS STRING) AS is_binary,
 CAST('Y' AS STRING) AS missing_means_zero;
CREATE TABLE @temp_database_schema.rwdfeatxcov_10 
USING DELTA
AS
SELECT
CAST(1000 + 8 AS BIGINT) AS covariate_id,
 row_id,
 days AS covariate_value
FROM
(
 SELECT 
 cohort.row_id AS row_id, 
 DATEDIFF(DAY, op.observation_period_start_date, cohort_start_date) AS days
 FROM @extraction_cohort cohort
 INNER JOIN @cdm_database_schema.observation_period op
 ON op.person_id = cohort.subject_id 
 AND op.observation_period_start_date <= cohort_start_date
 AND op.observation_period_end_date >= cohort_start_date
 ) raw_data;
INSERT INTO @temp_database_schema.rwdfeatxcov_ref (
 covariate_id,
 covariate_name,
 analysis_id,
 concept_id
 )
SELECT covariate_id,
 CAST('observation time (days) prior to index' AS STRING) AS covariate_name,
 8 AS analysis_id,
 0 AS concept_id
FROM (
 SELECT DISTINCT covariate_id
 FROM @temp_database_schema.rwdfeatxcov_10
 ) t1;
