DROP TABLE IF EXISTS @temp_database_schema.rwdfeatxgroups;
CREATE TABLE @temp_database_schema.rwdfeatxgroups
USING DELTA
AS
SELECT
DISTINCT descendant_concept_id,
 ancestor_concept_id
FROM
@cdm_database_schema.concept_ancestor
INNER JOIN @cdm_database_schema.concept
 ON ancestor_concept_id = concept_id
WHERE ((vocabulary_id = 'ATC'
 AND LENGTH(concept_code) IN (1, 3, 4, 5))
 OR (standard_concept = 'S' 
 AND concept_class_id = 'Ingredient'
 AND domain_id = 'Drug'))
 AND concept_id != 0
;
CREATE TABLE @temp_database_schema.rwdfeatxcov_11
USING DELTA
AS
SELECT
CAST(ancestor_concept_id AS BIGINT) * 1000 + 410 AS covariate_id,
 row_id,
 1 AS covariate_value 
FROM
(
 SELECT DISTINCT ancestor_concept_id,
 cohort.row_id AS row_id
 FROM @extraction_cohort cohort
 INNER JOIN @cdm_database_schema.drug_era
 ON cohort.subject_id = drug_era.person_id
 INNER JOIN @temp_database_schema.rwdfeatxgroups
 ON drug_concept_id = descendant_concept_id
 WHERE drug_era_start_date <= DATE_ADD(day,0,cohort.cohort_start_date)
AND 
drug_era_end_date 
>= DATE_ADD(day,-365,cohort.cohort_start_date)
 AND drug_concept_id != 0
) temp
;
TRUNCATE TABLE @temp_database_schema.rwdfeatxgroups;
DROP TABLE @temp_database_schema.rwdfeatxgroups;
INSERT INTO @temp_database_schema.rwdfeatxcov_ref (
 covariate_id,
 covariate_name,
 analysis_id,
 concept_id
 )
SELECT covariate_id,
 CAST(CONCAT('drug_era group (DrugGroupEraLongTerm) during day -365 through 0 days relative to index: ', CASE WHEN concept_name IS NULL THEN 'Unknown concept' ELSE concept_name END ) AS STRING) AS covariate_name,
 410 AS analysis_id,
 CAST((covariate_id - 410) / 1000 AS INT) AS concept_id
FROM (
 SELECT DISTINCT covariate_id
 FROM @temp_database_schema.rwdfeatxcov_11
 ) t1
LEFT JOIN @cdm_database_schema.concept
 ON concept_id = CAST((covariate_id - 410) / 1000 AS INT);
INSERT INTO @temp_database_schema.rwdfeatxanalysis_ref (
 analysis_id,
 analysis_name,
 domain_id,
 start_day,
 end_day,
 is_binary,
 missing_means_zero
 )
SELECT 410 AS analysis_id,
 CAST('DrugGroupEraLongTerm' AS STRING) AS analysis_name,
 CAST('Drug' AS STRING) AS domain_id,
 -365 AS start_day,
 0 AS end_day,
 CAST('Y' AS STRING) AS is_binary,
 CAST(NULL AS STRING) AS missing_means_zero;
